"""Подробная теория и практика внутри теории для 30 основных тем.

Каждая тема — список блоков в том порядке, в котором их увидит ученик:
заголовки, абзацы, примеры кода, таблицы трассировки, задания и ошибки.
Выводы примеров и ответы заданий здесь не пишутся вручную: expand_theory
запускает код, сохраняет настоящий результат и проверяет, что задания решаемы.
"""
import contextlib, io, sys

BLANK = '___'


def run(code, data=''):
    """Выполнить код с вводом data. Вернуть (вывод, строка ошибки или None)."""
    out, before = io.StringIO(), sys.stdin
    sys.stdin = io.StringIO(data)
    try:
        with contextlib.redirect_stdout(out):
            exec(compile(code, 'example.py', 'exec'), {'__name__': '__main__'})
        return out.getvalue(), None
    except SyntaxError as ex:
        return out.getvalue(), f'SyntaxError: {ex.msg}'
    except Exception as ex:
        return out.getvalue(), f'{type(ex).__name__}: {ex}'
    finally:
        sys.stdin = before


def clean(text):
    """Вывод для показа: без хвостовых пробелов в строках и пустых строк в конце."""
    return '\n'.join(line.rstrip() for line in text.rstrip().split('\n')) if text.strip() else ''


def H(text): return {'type': 'h', 'text': text}
def P(text): return {'type': 'p', 'text': text}
def C(code, data='', runnable=True): return {'type': 'code', 'code': code, 'input': data, 'runnable': runnable}
def TRACE(head, rows, note=''): return {'type': 'table', 'head': head, 'rows': [[str(c) for c in r] for r in rows], 'note': note}
def PREDICT(code, explain, data=''): return {'type': 'predict', 'code': code, 'input': data, 'explain': explain}
def FILL(goal, code, answers, inputs, hint): return {'type': 'fill', 'goal': goal, 'code': code, 'answers': answers, 'inputs': inputs, 'hint': hint}
def MINI(goal, starter, solution, inputs, hint, label='Мини-задача'): return {'type': 'mini', 'label': label, 'goal': goal, 'starter': starter, 'solution': solution, 'inputs': inputs, 'hint': hint}
def FIX(goal, starter, solution, inputs, hint): return MINI(goal, starter, solution, inputs, hint, 'Исправь ошибку')
def WRONG(wrong, right, why, data=''): return {'type': 'mistake', 'wrong': wrong, 'right': right, 'why': why, 'input': data}
def REMEMBER(*items): return {'type': 'remember', 'items': list(items)}


def _tests(code, inputs, where):
    tests = []
    for data in inputs:
        out, err = run(code, data)
        assert not err and clean(out), (where, data, err, out)
        tests.append({'input': data, 'expected': clean(out)})
    return tests


def _passes(code, tests):
    for t in tests:
        out, err = run(code, t['input'])
        if err or out.split() != t['expected'].split():
            return False
    return True


def prepare(ident, blocks):
    """Выполнить примеры, посчитать ответы заданий и проверить их."""
    result, drills = [], 0
    for i, block in enumerate(blocks):
        b, where = dict(block), f'{ident}[{i}]'
        kind = b['type']
        if kind == 'code' and b.pop('runnable'):
            out, err = run(b['code'], b['input'])
            assert not err, (where, err)
            b['output'] = clean(out)
        elif kind == 'code':
            compile(b['code'], where, 'exec')
        elif kind == 'predict':
            out, err = run(b['code'], b['input'])
            assert not err and clean(out), (where, err)
            b['answer'] = clean(out)
        elif kind == 'fill':
            parts = b['code'].split(BLANK)
            assert len(parts) == len(b['answers']) + 1 and b['inputs'], where
            full = parts[0] + ''.join(a + p for a, p in zip(b['answers'], parts[1:]))
            b['tests'] = _tests(full, b.pop('inputs'), where)
        elif kind == 'mini':
            b['tests'] = _tests(b['solution'], b.pop('inputs'), where)
            assert not _passes(b['starter'], b['tests']), (where, 'starter already passes')
        elif kind == 'mistake':
            out, err = run(b['wrong'], b['input'])
            b['wrongOut'] = err or clean(out)
            out, err = run(b['right'], b['input'])
            assert not err, (where, err)
            b['rightOut'] = clean(out)
            assert b['wrongOut'] != b['rightOut'], where
        if kind in ('predict', 'fill', 'mini'):
            b['id'] = f'{ident}-{drills}'
            drills += 1
        result.append(b)
    assert drills >= 3, (ident, 'at least three drills per topic')
    return result


def expand_theory(lessons):
    topics = {l['id']: l for l in lessons if l.get('day')}
    assert set(THEORY) == set(topics), set(topics) ^ set(THEORY)
    for ident, blocks in THEORY.items():
        topics[ident]['deep'] = prepare(ident, blocks)


