C('n = 6\nd = [0] * (n + 1)\nfor l, r, x in [(0, 2, 5), (1, 4, 2)]:\n    d[l] += x\n    d[r + 1] -= x\na, cur = [], 0\nfor i in range(n):\n    cur += d[i]\n    a.append(cur)\nprint(a)'),
