C('a = [2, 5, 5, 9, 12, 18]\nx = 9\nl, r = 0, len(a)\nwhile l < r:\n    m = (l + r) // 2\n    if a[m] < x:\n        l = m + 1\n    else:\n        r = m\nprint(l)'),
